osis_admin_page_start($pageTitle);
?>
<div class="admin-form-wrap"><a class="back-link" href="<?=osis_e(osis_url('admin/absensi/index.php'))?>">← Sesi absensi</a><div class="admin-panel form-panel"><span class="eyebrow">PENCATATAN KEHADIRAN</span><h2>Buat sesi baru</h2><?php if($error):?><div class="alert alert-error"><?=osis_e($error)?></div><?php endif;?><form method="post" data-validate-form><?=osis_csrf_input()?><label for="judul">Nama sesi</label><input id="judul" name="judul" required maxlength="180" placeholder="Contoh: Rapat Bulanan Oktober" value="<?=osis_e(isset($_POST['judul'])?$_POST['judul']:'')?>"><label for="tanggal">Tanggal</label><input id="tanggal" name="tanggal" type="date" required value="<?=osis_e(isset($_POST['tanggal'])?$_POST['tanggal']:date('Y-m-d'))?>"><label for="keterangan">Keterangan <span class="optional">(opsional)</span></label><textarea id="keterangan" name="keterangan" rows="4" placeholder="Catatan singkat untuk sesi ini..."><?=osis_e(isset($_POST['keterangan'])?$_POST['keterangan']:'')?></textarea><div class="form-actions"><a class="button button-outline" href="<?=osis_e(osis_url('admin/absensi/index.php'))?>">Batal</a><button class="button button-primary" type="submit">Buat sesi <span>↗</span></button></div></form></div></div>
